package com.restaurantmanagement.service.impl;
import com.restaurantmanagement.dto.*; import com.restaurantmanagement.entity.*; import com.restaurantmanagement.exception.NotFoundException; import com.restaurantmanagement.repository.*; import com.restaurantmanagement.service.OrderService; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime; import java.util.*;
@Service public class OrderServiceImpl implements OrderService { private final OrderRepository orders; private final RestaurantRepository restaurants; public OrderServiceImpl(OrderRepository o,RestaurantRepository r){orders=o;restaurants=r;} private OrderResponse map(CustomerOrder o){return new OrderResponse(o.id,o.externalOrderId,o.platform,o.customerName,o.total,o.status.name(),o.createdAt);}
@Transactional public OrderResponse create(OrderRequest r){ var existing=orders.findByIdempotencyKey(r.idempotencyKey()); if(existing.isPresent()) return map(existing.get()); var restaurant=restaurants.findById(r.restaurantId()).orElseThrow(()->new NotFoundException("Restaurant not found")); var o=new CustomerOrder();o.externalOrderId=r.externalOrderId();o.platform=r.platform();o.restaurant=restaurant;o.customerName=r.customerName();o.total=r.total();o.idempotencyKey=r.idempotencyKey(); return map(orders.save(o)); }
@Transactional(readOnly=true) public List<OrderResponse> list(){return orders.findAll().stream().sorted(Comparator.comparing((CustomerOrder o)->o.createdAt).reversed()).map(this::map).toList();}
@Transactional public OrderResponse transition(Long id,OrderStatus status){var o=orders.findById(id).orElseThrow(()->new NotFoundException("Order not found"));o.status=status;o.updatedAt=LocalDateTime.now();return map(o);}}
